  (mod) n (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
    (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ (Stdlib.Int.succ
    0))))))))

(** val bit_string_len_prop_dec : int -> (char list * int) -> bool **)

let bit_string_len_prop_dec n = function
| (l, n0) ->
  sumbool_and1 ((=) (length l) (get_list_len n))
    ((<) n0 (pow (Stdlib.Int.succ (Stdlib.Int.succ 0)) (get_tail_len n)))

(** val bit_string_format : int -> (char list * int) t_Format **)

let bit_string_format n =
  restrict_format
    (append_format (byte_list_format (get_list_len n))
      (basic_n_bit_format (get_tail_len n))) (bit_string_len_prop_dec n)

(** val ranged_nat_format : int -> int -> int t_Format **)

let ranged_nat_format lb ub =
  proj_format (ranged_int_format lb ub) BigArrayExtr.int_id
    BigArrayExtr.int_id (fun n ->
    sumbool_and1 (z_le_dec lb (BigArrayExtr.int_id n))
      (z_le_dec (BigArrayExtr.int_id n) ub))

(** val bit_string_ranged_format :
    int -> int -> (int * (char list * int)) t_Format **)

